<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:12px;margin-bottom:2px">Geiger–Rutherford gold-foil experiment</div>

<button id="btnFire">▶ Fire &alpha; beam</button>

<label>Gold foil thickness (atomic layers): <b id="thickVal">4</b>
  <input id="thick" type="range" min="1" max="20" step="1" value="4">
</label>

<div id="stats" style="font-size:11px;color:#333;line-height:1.45"></div>

<button id="btnLabels">Hide labels (quiz mode)</button>

