<div style="font-size:10.5px;color:#555;line-height:1.4">
  Drag to orbit: the luminescent screen is a <b>full circular band</b>, so a flash can be recorded at
  <i>any</i> scattering angle — even straight back toward the radium source.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ───────────────────────────────────────────────────────────
   lead source block      → BoxGeometry(3.4,2.2,2.4) MeshLambert grey  @(-8.5,0,0)
   block outlines         → EdgesGeometry + LineBasicMaterial #3A3A3A
   source cavity          → EdgesGeometry(Box 1.8,1.0,1.0) LineDashedMaterial (depthTest off)
   radium sample          → SphereGeometry(0.14) basic #6EBE44 + RingGeometry halo white (billboard)
   collimating aperture   → BoxGeometry(0.10,0.70,0.35) basic #2E2E2E on +X face @x=-6.78
   alpha beam             → CylinderGeometry(r=0.09,len=8.5) #6EBE44 + bright core cyl r=0.04 #9FE05A
   thin gold foil         → BoxGeometry(0.12,1.1,0.7) standard #F0BE2E emissive, rot.y 8°, + gold edges
   luminescent screen     → 2 open CylinderGeometry (ri 3.4 / ro 3.55, h 1.6, angular gap on -X)
                            + 2 RingGeometry rims #8F9396 at y = ±0.8
   trajectories           → THREE.Line polylines foil→inner wall (straight / slight / large)
   travelling particles   → THREE.Points, drawRange packed, #5FAF2E
   scintillation flashes  → SphereGeometry(0.12) basic #A8E45C, fading opacity + growing scale
   labels                 → addLabel() HTML, leader lines = THREE.Line black
──────────────────────────────────────────────────────────────────────────── */

/* ── lighting ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.68));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.62);
keyLight.position.set(3, 5, 10);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.22);
fillLight.position.set(-6, 4, -6);
scene.add(fillLight);

const GREEN = 0x6EBE44, GREEN_LT = 0x9FE05A, RAY_C = 0x72C13C;
const BEAM_X0 = -8.5, BEAM_LEN = 8.5;
const RI = 3.4, RO = 3.55, HH = 0.8;

/* ── 1. lead radium-source block ─────────────────────────────────────────── */
const boxGroup = new THREE.Group();
const boxMesh = new THREE.Mesh(
  new THREE.BoxGeometry(3.4, 2.2, 2.4),
  new THREE.MeshLambertMaterial({ color: 0xBDBDBD })
);
boxMesh.position.set(-8.5, 0, 0);
boxGroup.add(boxMesh);
const boxEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(boxMesh.geometry),
  new THREE.LineBasicMaterial({ color: 0x3A3A3A })
);
boxEdges.position.copy(boxMesh.position);
boxGroup.add(boxEdges);
scene.add(boxGroup);
registerInteractive(boxMesh, {
  title: 'Lead source block',
  tooltip: 'Lead block housing the radium',
  body: 'A block of lead absorbs alpha particles emitted in every direction except those that escape through a narrow channel, producing a collimated beam.'
});

/* dashed cavity outline (drawn through the block, as in the printed figure) */
const cavity = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(1.8, 1.0, 1.0)),
  new THREE.LineDashedMaterial({ color: 0x2E2E2E, dashSize: 0.13, gapSize: 0.09, depthTest: false })
);
cavity.position.set(-8.5, 0, 0);
cavity.computeLineDistances();
cavity.renderOrder = 5;
boxGroup.add(cavity);

/* radium sample: green dot + white halo ring */
const radium = new THREE.Mesh(
  new THREE.SphereGeometry(0.14, 20, 16),
  new THREE.MeshBasicMaterial({ color: GREEN, depthTest: false })
);
radium.position.set(BEAM_X0, 0, 0);
radium.renderOrder = 7;
boxGroup.add(radium);
const halo = new THREE.Mesh(
  new THREE.RingGeometry(0.17, 0.25, 28),
  new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide, depthTest: false })
);
halo.position.set(BEAM_X0, 0, 0);
halo.renderOrder = 6;
boxGroup.add(halo);
registerInteractive(radium, {
  title: 'Radium source',
  tooltip: 'Radium: the α-particle source',
  body: 'Radium decays by alpha emission. Each alpha particle is a helium nucleus: 2 protons + 2 neutrons, charge +2.'
});

/* collimating aperture on the +X face */
const aperture = new THREE.Mesh(
  new THREE.BoxGeometry(0.10, 0.70, 0.35),
  new THREE.MeshLambertMaterial({ color: 0x3C3C3C })
);
aperture.position.set(-6.76, 0, 0);
boxGroup.add(aperture);

/* ── 2. collimated alpha beam ─────────────────────────────────────────────── */
const beamMesh = new THREE.Mesh(
  new THREE.CylinderGeometry(0.09, 0.09, BEAM_LEN, 18, 1, false),
  new THREE.MeshBasicMaterial({ color: GREEN })
);
beamMesh.rotation.z = -Math.PI / 2;
beamMesh.position.set(BEAM_X0 + BEAM_LEN / 2, 0, 0);
scene.add(beamMesh);
registerInteractive(beamMesh, {
  title: 'Beam of α particles',
  tooltip: 'Collimated α-particle beam',
  body: 'Only alphas travelling along the channel escape the lead block, so a narrow parallel beam strikes the foil.'
});

const beamCore = new THREE.Mesh(
  new THREE.CylinderGeometry(0.04, 0.04, 6.5, 12, 1, false),
  new THREE.MeshBasicMaterial({ color: GREEN_LT, depthTest: false })
);
beamCore.rotation.z = -Math.PI / 2;
beamCore.position.set(-3.4, 0, 0);
beamCore.renderOrder = 3;
scene.add(beamCore);

/* ── 3. thin gold foil ────────────────────────────────────────────────────── */
const foil = new THREE.Mesh(
  new THREE.BoxGeometry(0.12, 1.1, 0.7),
  new THREE.MeshStandardMaterial({
    color: 0xF0BE2E, emissive: 0x6A4E08, roughness: 0.45, metalness: 0.35
  })
);
foil.rotation.y = THREE.MathUtils.degToRad(8);
scene.add(foil);
const foilEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(foil.geometry),
  new THREE.LineBasicMaterial({ color: 0xC9962A })
);
foilEdges.rotation.copy(foil.rotation);
scene.add(foilEdges);
registerInteractive(foil, {
  title: 'Thin gold foil',
  tooltip: 'Thin gold foil (a few thousand atoms thick)',
  body: 'Gold can be hammered into a foil only a few thousand atoms thick. Almost all of its volume is empty space, so most alpha particles cross it without deviating.'
});

/* ── 4. luminescent screen: open circular band ────────────────────────────── */
const GAP = 0.20;                                   // angular gap on the -X side
const wallMatIn = new THREE.MeshLambertMaterial({ color: 0xDCE7DC, side: THREE.DoubleSide });
const wallMatOut = new THREE.MeshLambertMaterial({ color: 0xF2F2F2, side: THREE.DoubleSide });
const innerWall = new THREE.Mesh(
  new THREE.CylinderGeometry(RI, RI, 2 * HH, 128, 1, true, -Math.PI / 2 + GAP / 2, Math.PI * 2 - GAP),
  wallMatIn
);
const outerWall = new THREE.Mesh(
  new THREE.CylinderGeometry(RO, RO, 2 * HH, 128, 1, true, -Math.PI / 2 + GAP / 2, Math.PI * 2 - GAP),
  wallMatOut
);
scene.add(innerWall, outerWall);
const rimMat = new THREE.MeshLambertMaterial({ color: 0x8F9396, side: THREE.DoubleSide });
for (const sy of [1, -1]) {
  const rim = new THREE.Mesh(
    new THREE.RingGeometry(RI, RO, 128, 1, Math.PI + GAP / 2, Math.PI * 2 - GAP),
    rimMat
  );
  rim.rotation.x = -Math.PI / 2;
  rim.position.y = sy * HH;
  scene.add(rim);
}
registerInteractive(innerWall, {
  title: 'Luminescent (zinc sulfide) screen',
  tooltip: 'Luminescent screen — flashes where an α lands',
  body: 'Each alpha particle that strikes the zinc-sulfide coating makes a tiny flash of light. Because the screen forms a complete circle around the foil, a flash can be counted at any scattering angle — including backwards.'
});

/* ── 5. trajectories from the foil to the inner wall ──────────────────────── */
function dirFrom(azDeg, elDeg) {
  const a = THREE.MathUtils.degToRad(azDeg), e = THREE.MathUtils.degToRad(elDeg);
  return new THREE.Vector3(Math.cos(a) * Math.cos(e), Math.sin(e), Math.sin(a) * Math.cos(e));
}
function makeRay(azDeg, elDeg, color, width) {
  const dir = dirFrom(azDeg, elDeg);
  const t = RI / Math.hypot(dir.x, dir.z);
  const end = dir.clone().multiplyScalar(t);
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), end]),
    new THREE.LineBasicMaterial({ color: color, transparent: true, opacity: 0.95, linewidth: width || 1 })
  );
  scene.add(line);
  return { dir, end, len: end.length(), line };
}

const rayStraight = makeRay(0, 0, 0x5FAF2E);
