  new THREE.EdgesGeometry(new THREE.BoxGeometry(1.8, 1.0, 1.0)),
  new THREE.LineDashedMaterial({ color: 0x2E2E2E, dashSize: 0.13, gapSize: 0.09, depthTest: false })
);
cavity.position.set(-8.5, 0, 0);
cavity.computeLineDistances();
cavity.renderOrder = 5;
boxGroup.add(cavity);

/* radium sample: green dot + white halo ring */
const radium = new THREE.Mesh(
  new THREE.SphereGeometry(0.14, 20, 16),
  new THREE.MeshBasicMaterial({ color: GREEN, depthTest: false })
);
radium.position.set(BEAM_X0, 0, 0);
radium.renderOrder = 7;
boxGroup.add(radium);
const halo = new THREE.Mesh(
  new THREE.RingGeometry(0.17, 0.25, 28),
  new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide, depthTest: false })
);
halo.position.set(BEAM_X0, 0, 0);
halo.renderOrder = 6;
boxGroup.add(halo);
registerInteractive(radium, {
  title: 'Radium source',
  tooltip: 'Radium: the α-particle source',
  body: 'Radium decays by alpha emission. Each alpha particle is a helium nucleus: 2 protons + 2 neutrons, charge +2.'
});

/* collimating aperture on the +X face */
const aperture = new THREE.Mesh(
  new THREE.BoxGeometry(0.10, 0.70, 0.35),
  new THREE.MeshLambertMaterial({ color: 0x3C3C3C })
);
aperture.position.set(-6.76, 0, 0);
boxGroup.add(aperture);

/* ── 2. collimated alpha beam ─────────────────────────────────────────────── */
const beamMesh = new THREE.Mesh(
  new THREE.CylinderGeometry(0.09, 0.09, BEAM_LEN, 18, 1, false),
  new THREE.MeshBasicMaterial({ color: GREEN })
);
beamMesh.rotation.z = -Math.PI / 2;
beamMesh.position.set(BEAM_X0 + BEAM_LEN / 2, 0, 0);
scene.add(beamMesh);
registerInteractive(beamMesh, {
  title: 'Beam of α particles',
  tooltip: 'Collimated α-particle beam',
  body: 'Only alphas travelling along the channel escape the lead block, so a narrow parallel beam strikes the foil.'
});

const beamCore = new THREE.Mesh(
  new THREE.CylinderGeometry(0.04, 0.04, 6.5, 12, 1, false),
  new THREE.MeshBasicMaterial({ color: GREEN_LT, depthTest: false })
);
beamCore.rotation.z = -Math.PI / 2;
beamCore.position.set(-3.4, 0, 0);
beamCore.renderOrder = 3;
scene.add(beamCore);

/* ── 3. thin gold foil ────────────────────────────────────────────────────── */
const foil = new THREE.Mesh(
  new THREE.BoxGeometry(0.12, 1.1, 0.7),
  new THREE.MeshStandardMaterial({
    color: 0xF0BE2E, emissive: 0x6A4E08, roughness: 0.45, metalness: 0.35
  })
);
foil.rotation.y = THREE.MathUtils.degToRad(8);
scene.add(foil);
const foilEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(foil.geometry),
  new THREE.LineBasicMaterial({ color: 0xC9962A })
);
foilEdges.rotation.copy(foil.rotation);
scene.add(foilEdges);
registerInteractive(foil, {
  title: 'Thin gold foil',
  tooltip: 'Thin gold foil (a few thousand atoms thick)',
  body: 'Gold can be hammered into a foil only a few thousand atoms thick. Almost all of its volume is empty space, so most alpha particles cross it without deviating.'
});

/* ── 4. luminescent screen: open circular band ────────────────────────────── */
const GAP = 0.20;                                   // angular gap on the -X side
const wallMatIn = new THREE.MeshLambertMaterial({ color: 0xDCE7DC, side: THREE.DoubleSide });
const wallMatOut = new THREE.MeshLambertMaterial({ color: 0xF2F2F2, side: THREE.DoubleSide });
const innerWall = new THREE.Mesh(
  new THREE.CylinderGeometry(RI, RI, 2 * HH, 128, 1, true, -Math.PI / 2 + GAP / 2, Math.PI * 2 - GAP),
  wallMatIn
);
const outerWall = new THREE.Mesh(
  new THREE.CylinderGeometry(RO, RO, 2 * HH, 128, 1, true, -Math.PI / 2 + GAP / 2, Math.PI * 2 - GAP),
  wallMatOut
);
scene.add(innerWall, outerWall);
const rimMat = new THREE.MeshLambertMaterial({ color: 0x8F9396, side: THREE.DoubleSide });
for (const sy of [1, -1]) {
  const rim = new THREE.Mesh(
    new THREE.RingGeometry(RI, RO, 128, 1, Math.PI + GAP / 2, Math.PI * 2 - GAP),
    rimMat
  );
  rim.rotation.x = -Math.PI / 2;
  rim.position.y = sy * HH;
  scene.add(rim);
}
registerInteractive(innerWall, {
  title: 'Luminescent (zinc sulfide) screen',
  tooltip: 'Luminescent screen — flashes where an α lands',
  body: 'Each alpha particle that strikes the zinc-sulfide coating makes a tiny flash of light. Because the screen forms a complete circle around the foil, a flash can be counted at any scattering angle — including backwards.'
});

/* ── 5. trajectories from the foil to the inner wall ──────────────────────── */
function dirFrom(azDeg, elDeg) {
  const a = THREE.MathUtils.degToRad(azDeg), e = THREE.MathUtils.degToRad(elDeg);
  return new THREE.Vector3(Math.cos(a) * Math.cos(e), Math.sin(e), Math.sin(a) * Math.cos(e));
}
function makeRay(azDeg, elDeg, color, width) {
  const dir = dirFrom(azDeg, elDeg);
  const t = RI / Math.hypot(dir.x, dir.z);
  const end = dir.clone().multiplyScalar(t);
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), end]),
    new THREE.LineBasicMaterial({ color: color, transparent: true, opacity: 0.95, linewidth: width || 1 })
  );
  scene.add(line);
  return { dir, end, len: end.length(), line };
}

const rayStraight = makeRay(0, 0, 0x5FAF2E);
registerInteractive(rayStraight.line, {
  title: 'Most α particles pass straight through',
  tooltip: 'Undeflected: ~99% of the beam',
  body: 'The overwhelming majority of alphas pass through the foil as if it were not there — evidence that the atom is mostly empty space.'
});

const slightSpecs = [[6, 5], [-9, -6], [13, 2], [-15, 7], [21, -4], [-24, -8], [11, -10], [-6, 9], [28, 6], [-30, -3]];
const slightRays = slightSpecs.map(s => makeRay(s[0], s[1], RAY_C));
slightRays.forEach(r => registerInteractive(r.line, {
  title: 'A few α particles are slightly deflected',
  tooltip: 'Small-angle deflection',
  body: 'Alphas that pass near a nucleus feel its positive charge and are nudged through a small angle. Thicker foil = more of these.'
}));

const largeSpecs = [[65, 8], [-75, -7], [155, 6], [-160, -6]];
const largeRays = largeSpecs.map(s => makeRay(s[0], s[1], 0x4F9A25));
largeRays.forEach(r => registerInteractive(r.line, {
  title: 'A very small number are significantly deflected',
  tooltip: 'Large-angle scattering / backscatter',
  body: 'About 1 in 8000 alphas is turned through a huge angle, some almost straight back. Only a single collision with a tiny, massive, highly charged nucleus can do this.'
}));
const allRays = [rayStraight].concat(slightRays, largeRays);

/* ── 6. scintillation flash pool ──────────────────────────────────────────── */
const flashes = [];
for (let i = 0; i < 40; i++) {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 12, 10),
    new THREE.MeshBasicMaterial({ color: 0xA8E45C, transparent: true, opacity: 0, depthWrite: false })
  );
  m.visible = false;
  scene.add(m);
  flashes.push({ mesh: m, life: 0 });
}
function spawnFlash(p) {
  let f = flashes.find(x => x.life <= 0);
  if (!f) f = flashes[0];
  f.mesh.position.copy(p).multiplyScalar(0.985);
  f.mesh.visible = true;
  f.life = 0.5;
}

/* ── 7. travelling particles ──────────────────────────────────────────────── */
const PMAX = 400;
const pArr = new Float32Array(PMAX * 3);
const pGeo = new THREE.BufferGeometry();
pGeo.setAttribute('position', new THREE.BufferAttribute(pArr, 3));
pGeo.setDrawRange(0, 0);
const points = new THREE.Points(pGeo, new THREE.PointsMaterial({
  color: 0x4E9E22, size: 0.19, sizeAttenuation: true, depthWrite: false
}));
points.frustumCulled = false;
scene.add(points);
const particles = [];

/* ── camera ───────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 15, rollDeg: 0, heightFraction: 0.6 });
controls.minPolarAngle = THREE.MathUtils.degToRad(20);   // elevation ≤ 70°
controls.maxPolarAngle = THREE.MathUtils.degToRad(85);   // elevation ≥ 5°
document.getElementById('btnReset').style.display = '';

/* ── labels + leader lines ────────────────────────────────────────────────── */
const leaderGroup = new THREE.Group();
scene.add(leaderGroup);
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000 });
function leader(a, b) {
  leaderGroup.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(...a), new THREE.Vector3(...b)]),
    leaderMat
  ));
}
const LF = '42px';
const labelEntries = [];
function L(html, pos, opts) {
  labelEntries.push(addLabel(html, new THREE.Vector3(...pos), Object.assign({ fontSize: LF }, opts || {})));
}

L('Radium source of &alpha; particles', [-9.1, -3.45, 0]);
leader([-9.1, -3.05, 0], [-8.55, -0.28, 0]);

L('Beam of<br>&alpha; particles', [-4.8, 3.1, 0]);
leader([-4.8, 2.45, 0], [-4.8, 0.22, 0]);

L('A very small number<br>of &alpha; particles<br>are significantly<br>deflected', [-3.7, 4.25, 0]);
leader([-3.1, 3.35, 0], [-1.55, 0.2, 0.72]);

L('A few &alpha;<br>particles are<br>slightly deflected', [0.85, 4.45, 0]);
leader([0.85, 3.75, 0], [1.75, 0.16, 0.19]);

L('Most &alpha; particles<br>pass straight<br>through foil', [4.1, 4.45, 0]);
leader([3.9, 3.75, 0], [2.65, 0.0, 0.0]);

L('Luminescent screen<br>to detect scattered<br>&alpha; particles', [-1.0, -3.7, 1.6]);
leader([-1.0, -3.05, 1.6], [-1.44, -0.52, 3.05]);

L('Thin gold<br>foil', [2.35, -3.5, 0]);
leader([2.1, -2.95, 0], [0.16, -0.60, 0]);

/* ── UI wiring ────────────────────────────────────────────────────────────── */
const btnFire = document.getElementById('btnFire');
const btnLabels = document.getElementById('btnLabels');
const thickInput = document.getElementById('thick');
const thickVal = document.getElementById('thickVal');
const statsDiv = document.getElementById('stats');

let firing = false;
let layers = 4, layersTarget = 4;
let labelsOn = true;
let counts = { total: 0, through: 0, slight: 0, large: 0 };

function slightFraction(n) { return 0.5 * (1 - Math.exp(-0.04 * n)); }
const LARGE_FRACTION = 1 / 60;

function updateStats() {
  const s = slightFraction(layers), l = LARGE_FRACTION, t = 1 - s - l;
  const pc = x => (x * 100).toFixed(1) + '%';
  statsDiv.innerHTML =
    'Per-particle chance at ' + Math.round(layers) + ' layer' + (Math.round(layers) === 1 ? '' : 's') + ':<br>' +
    '&nbsp;straight through <b>' + pc(t) + '</b><br>' +
    '&nbsp;slight deflection <b>' + pc(s) + '</b><br>' +
    '&nbsp;large angle <b>' + pc(l) + '</b> (fixed)<br>' +
    'Counted flashes: <b>' + counts.total + '</b> &nbsp;(' +
    counts.through + ' / ' + counts.slight + ' / ' + counts.large + ')';
}

function applyLayers() {
  foil.scale.x = (0.06 + 0.015 * layers) / 0.12;
  foilEdges.scale.x = foil.scale.x;
  const nShown = Math.max(3, Math.min(slightRays.length, Math.round(3 + layers * 0.45)));
  slightRays.forEach((r, i) => { r.line.visible = i < nShown; });
  updateStats();
}

function setFiring(on) {
  firing = on;
  btnFire.textContent = on ? '■ Stop beam' : '▶ Fire α beam';
  btnFire.classList.toggle('active', on);
}
function setLabels(on) {
  labelsOn = on;
  labelEntries.forEach(e => { e.div.style.visibility = on ? 'visible' : 'hidden'; });
  leaderGroup.visible = on;
  btnLabels.textContent = on ? 'Hide labels (quiz mode)' : 'Show labels';
  btnLabels.classList.toggle('active', !on);
}

btnFire.addEventListener('click', () => setFiring(!firing));
btnLabels.addEventListener('click', () => setLabels(!labelsOn));
thickInput.addEventListener('input', () => {
  layersTarget = parseFloat(thickInput.value);
  layers = layersTarget;
  thickVal.textContent = Math.round(layers);
  applyLayers();
});

/* ── guided demo ──────────────────────────────────────────────────────────── */
const steps = [
  {
    title: 'The apparatus',
    narration: 'A radium source sealed in a lead block emits a narrow beam of alpha particles toward a thin gold foil at the centre of a circular luminescent screen.',
    state: { showLabels: true, foilThickness: 4, fireBeam: false }
  },
  {
    title: 'Fire the beam',
    narration: 'Particles stream through the foil. Almost every one flashes the screen directly opposite the beam — the foil is mostly empty space.',
    state: { showLabels: true, foilThickness: 4, fireBeam: true }
  },
  {
    title: 'Thicker foil',
    narration: 'Adding atomic layers produces many more small-angle deflections spread around the forward part of the screen, yet large-angle backscatter remains just as rare.',
    state: { showLabels: true, foilThickness: 16, fireBeam: true }
  },
  {
    title: 'Quiz yourself',
    narration: 'With the labels hidden, name each part of the apparatus and each of the three particle outcomes.',
    state: { showLabels: false, foilThickness: 4, fireBeam: true }
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const st = steps[stepIdx];
  setLabels(st.state.showLabels);
  layersTarget = st.state.foilThickness;
  setFiring(st.state.fireBeam);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.narration;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── animation loop (particles, flashes, tweens, billboard) ───────────────── */
let _t0 = performance.now(), spawnAcc = 0;
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _t0) / 1000);
  _t0 = now;

  /* thickness tween (driven by the demo steps) */
  if (Math.abs(layers - layersTarget) > 0.01) {
    layers += (layersTarget - layers) * Math.min(1, dt * 5);
    thickInput.value = String(Math.round(layers));
    thickVal.textContent = Math.round(layers);
    applyLayers();
  }

  /* spawn */
  if (firing) {
    spawnAcc += dt * 22;
    while (spawnAcc >= 1 && particles.length < PMAX) {
      spawnAcc -= 1;
      const r = Math.random();
      const sF = slightFraction(layers);
      let ray, kind;
      if (r < LARGE_FRACTION) {
        ray = largeRays[(Math.random() * largeRays.length) | 0]; kind = 'large';
      } else if (r < LARGE_FRACTION + sF) {
        const vis = slightRays.filter(x => x.line.visible);
        ray = vis[(Math.random() * vis.length) | 0]; kind = 'slight';
      } else {
        ray = rayStraight; kind = 'through';
      }
      particles.push({ s: 0, speed: 15 + Math.random() * 4, ray, kind, total: BEAM_LEN + ray.len });
    }
  } else {
    spawnAcc = 0;
  }

  /* advance + pack into the buffer */
  let n = 0;
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.s += p.speed * dt;
    if (p.s >= p.total) {
      spawnFlash(p.ray.end);
      counts.total++; counts[p.kind]++;
      particles.splice(i, 1);
      continue;
    }
    let x, y, z;
    if (p.s < BEAM_LEN) { x = BEAM_X0 + p.s; y = 0; z = 0; }
    else { const u = p.s - BEAM_LEN; x = p.ray.dir.x * u; y = p.ray.dir.y * u; z = p.ray.dir.z * u; }
    pArr[n * 3] = x; pArr[n * 3 + 1] = y; pArr[n * 3 + 2] = z;
    n++;
  }
  pGeo.setDrawRange(0, n);
  pGeo.attributes.position.needsUpdate = true;
  if (counts.total && (counts.total % 5 === 0)) updateStats();

  /* flashes */
  for (const f of flashes) {
    if (f.life <= 0) continue;
    f.life -= dt;
    const k = Math.max(0, f.life / 0.5);
    f.mesh.material.opacity = k;
    const s = 1.9 - 1.2 * k;
    f.mesh.scale.setScalar(s);
    if (f.life <= 0) { f.mesh.visible = false; f.mesh.material.opacity = 0; }
  }

  /* billboard the white halo around the radium sample */
  halo.quaternion.copy(camera.quaternion);
}

applyLayers();
goToStep(0);
tick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

