    thickVal.textContent = Math.round(layers);
    applyLayers();
  }

  /* spawn */
  if (firing) {
    spawnAcc += dt * 24;
    while (spawnAcc >= 1 && particles.length < PMAX) {
      spawnAcc -= 1;
      const r = Math.random();
      const sF = slightFraction(layers);
      let ray, kind;
      if (r < LARGE_FRACTION) {
        ray = largeRays[(Math.random() * largeRays.length) | 0]; kind = 'large';
      } else if (r < LARGE_FRACTION + sF) {
        const vis = slightRays.filter(x => x.mesh.visible);
        ray = vis[(Math.random() * vis.length) | 0]; kind = 'slight';
      } else {
        ray = rayStraight; kind = 'through';
      }
      particles.push({ s: 0, speed: 15 + Math.random() * 4, ray, kind, total: BEAM_LEN + ray.len });
    }
  } else {
    spawnAcc = 0;
  }

  /* advance + pack into the buffer */
  let n = 0;
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.s += p.speed * dt;
    if (p.s >= p.total) {
      spawnFlash(p.ray.end);
      counts.total++; counts[p.kind]++;
      particles.splice(i, 1);
      continue;
    }
    let x, y, z;
    if (p.s < BEAM_LEN) { x = BEAM_X0 + p.s; y = 0; z = 0; }
    else { const u = p.s - BEAM_LEN; x = p.ray.dir.x * u; y = p.ray.dir.y * u; z = p.ray.dir.z * u; }
    pArr[n * 3] = x; pArr[n * 3 + 1] = y; pArr[n * 3 + 2] = z;
    n++;
  }
  pGeo.setDrawRange(0, n);
  pGeo.attributes.position.needsUpdate = true;
  if (counts.total && (counts.total % 5 === 0)) updateStats();

