const _UP = new THREE.Vector3(0, 1, 0);
function makeRay(azDeg, elDeg, color, radius) {
  const dir = dirFrom(azDeg, elDeg);
  const t = RI / Math.hypot(dir.x, dir.z);
  const end = dir.clone().multiplyScalar(t);
  const len = end.length();
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, 10, 1, true),
    new THREE.MeshBasicMaterial({ color })
  );
  mesh.quaternion.setFromUnitVectors(_UP, dir.clone().normalize());
  mesh.position.copy(end).multiplyScalar(0.5);
  mesh.renderOrder = 4;
  scene.add(mesh);
  return { dir, end, len, mesh };
}

