/* ── labels + leader lines (positions mapped from the source figure) ─────── */
const _camDist = camera.position.distanceTo(controls.target);
const LF = (14 * _camDist / 8).toFixed(1) + 'px';        // ≈14 px on screen

const leaderGroup = new THREE.Group();
scene.add(leaderGroup);
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000, depthTest: false, depthWrite: false });
function leader(a, b) {
  const l = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(...a), new THREE.Vector3(...b)]),
    leaderMat
  );
  l.renderOrder = 14;
