L('A few &alpha;<br>particles are<br>slightly deflected', [-0.34, 2.45, 0]);
leader([-0.42, 1.70, 0], [1.34, 0.17, -0.38]);

L('Most &alpha; particles<br>pass straight<br>through foil', [1.66, 2.45, 0]);
leader([1.48, 1.72, 0], [1.48, 0.08, 0]);

L('Luminescent screen<br>to detect scattered<br>&alpha; particles', [-1.98, -2.58, 0]);
leader([-1.62, -1.98, 0], [-0.62, -0.78, 3.28]);

L('Thin gold<br>foil', [0.82, -2.52, 0]);
leader([0.62, -1.96, 0], [0.07, -0.50, 0.10]);

/* ── UI wiring ────────────────────────────────────────────────────────────── */
const btnFire = document.getElementById('btnFire');
const btnLabels = document.getElementById('btnLabels');
const thickInput = document.getElementById('thick');
const thickVal = document.getElementById('thickVal');
const statsDiv = document.getElementById('stats');

let firing = false;
let layers = 4, layersTarget = 4;
let labelsOn = true;
let counts = { total: 0, through: 0, slight: 0, large: 0 };

/* ≈2 % per atomic layer, saturating */
function slightFraction(n) { return 0.5 * (1 - Math.exp(-0.04 * n)); }
const LARGE_REAL = 1 / 8000;   // physical large-angle rate (thickness-independent)
const LARGE_VIS = 1 / 60;      // exaggerated so the animation actually shows one

function updateStats() {
  const s = slightFraction(layers);
  const t = 1 - s - LARGE_REAL;
  const pc = x => (x * 100).toFixed(1) + '%';
  statsDiv.innerHTML =
    'Per &alpha; particle at ' + Math.round(layers) + ' layer' + (Math.round(layers) === 1 ? '' : 's') + ':<br>' +
    '&nbsp;straight through <b>' + pc(t) + '</b><br>' +
    '&nbsp;slight deflection <b>' + pc(s) + '</b><br>' +
    '&nbsp;large angle <b>1 in 8000</b> (0.0125%) —<br>&nbsp;<i>unchanged by thickness</i><br>' +
    '<span style="color:#666">animation exaggerates large angles to 1 in 60 so they are visible</span><br>' +
    'Flashes counted: <b>' + counts.total + '</b><br>' +
    '&nbsp;through ' + counts.through + ' · slight ' + counts.slight + ' · large ' + counts.large;
}

function applyLayers() {
  const sx = (0.07 + 0.012 * layers) / 0.12;
