  },
  {
    title: 'Fire the beam',
    narration: 'Particles stream through the foil. Almost every one flashes the screen directly opposite the beam — the foil is mostly empty space.',
    state: { showLabels: true, foilThickness: 4, fireBeam: true }
  },
  {
    title: 'Thicker foil',
    narration: 'Adding atomic layers produces many more small-angle deflections spread around the forward part of the screen, yet the large-angle backscatter rate stays at about 1 in 8000 — those come from single close encounters, not from many small pushes.',
    state: { showLabels: true, foilThickness: 16, fireBeam: true }
  },
  {
    title: 'Quiz yourself',
    narration: 'With the labels hidden, name each part of the apparatus and each of the three particle outcomes. Hover a part to check your answer.',
    state: { showLabels: false, foilThickness: 4, fireBeam: true }
